INSERT INTO feature VALUES('stage-typing','recursion','Stage-typed descent','structural-recursion','implemented','notable',NULL,'A marked call checks where its argument stands below the stage of the parameter it descends on, in both checkers; the accessibility rule stages every placed occurrence of a stratified family; a transport along a path in a set keeps its value''s stage, and one along any other path is refused by name.','core-checker kernel-core','corpus/fragment/stage-not-below.gandr corpus/model/data/stratified.gandr corpus/pathological/data/curry.gandr corpus/model/data/typed-evaluator.gandr corpus/ledger/diagnostics/StageNotCarried.gandr','corpus/model/data/stratified.gandr',NULL);
